"""One consumer journey over existing screens, with reversible source selection.

The router owns history, not financial authority. Source selection is enforced
atomically by the authenticated API and invalidates the shared model revision.
"""

NAVIGATION_CSS = r'''
.friday-nav .studio-mobile-chat{display:inline-flex!important}.journey-bar{display:flex;align-items:center;justify-content:space-between;gap:12px;margin:0 0 18px;flex-wrap:wrap}.journey-bar button,.journey-actions button{min-height:44px;font-size:12px}.journey-bar p{margin:0;font-size:12px;color:var(--muted)}.journey-actions{display:flex;gap:9px;flex-wrap:wrap;align-items:center}.journey-source{padding:16px 20px;border-radius:18px;background:var(--studio-lilac);margin:0 0 20px;display:flex;gap:12px;align-items:center;justify-content:space-between}.journey-source p{font-size:12px;line-height:1.6;margin:4px 0;color:var(--muted)}.journey-source strong{font-size:13px}.journey-source button{flex:none;min-height:44px;font-size:12px}.journey-library{display:grid;gap:14px}.journey-library-row{display:grid;grid-template-columns:24px minmax(0,1fr);gap:12px;align-items:start;padding:20px;border:1px solid var(--line);background:var(--panel);border-radius:20px;cursor:pointer}.journey-library-row input{width:19px!important;height:19px;margin-top:3px;accent-color:var(--blue)}.journey-library-row strong{display:block;font-size:14px}.journey-library-row small{display:block;margin-top:7px;color:var(--muted);line-height:1.65;font-size:12px;overflow-wrap:anywhere}.journey-library-row:has(input:checked){border-color:var(--blue);background:var(--studio-lilac)}.journey-library-row details{margin-top:10px;font-size:12px}.journey-library-row summary{min-height:44px;align-content:center}.journey-status{font-size:12px;line-height:1.7;color:var(--muted);min-height:22px}.journey-empty{padding:26px;border:1px dashed var(--line);border-radius:22px}.journey-empty h2{font-size:22px}.journey-source-list{font-size:12px;line-height:1.7;padding-left:18px}.journey-tools{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin:20px 0}.journey-tools button{text-align:left;min-height:70px}.journey-listen{min-height:44px;font-size:12px;white-space:nowrap}.journey-progress{font-size:12px;color:var(--muted);margin:0 0 15px}.journey-source[data-empty=true]{background:var(--panel2)}
@media(max-width:600px){.journey-source{display:block;padding:16px}.journey-source button{margin-top:10px}.journey-tools{grid-template-columns:1fr}.journey-bar{align-items:flex-start}.journey-library-row{padding:16px}.journey-actions{width:100%}.journey-actions button{flex:1}.journey-listen{padding:8px 12px!important}}
.topbar,.topbar .shell{height:auto!important}.studio-workspace .screen-back{width:auto;min-width:64px;min-height:44px;padding:8px 12px;text-align:left;background:transparent;border-radius:12px;box-shadow:none}
.friday-nav button[aria-current=location]{background:var(--studio-lilac);color:var(--blue)}
.journey-sample-guide{display:block;width:fit-content;position:relative;z-index:2;min-height:44px;padding:12px 0;font-size:13px;color:var(--blue);text-underline-offset:4px}.journey-sample-guide:focus-visible{outline:3px solid var(--blue);outline-offset:4px;border-radius:6px}
@media(max-width:1450px){.topbar .shell{flex-wrap:wrap;gap:12px;padding-top:12px;padding-bottom:12px}.topbar .friday-nav{position:static;order:5;flex:1 0 100%;width:100%;min-width:0;display:flex;flex-direction:row;gap:6px;overflow-x:auto;justify-content:space-between}.topbar .friday-nav button{flex:1;min-width:max-content}.topbar .friday-preference-actions{margin-left:auto}.topbar .studio-account{margin-left:0}}
@media(max-width:600px){.topbar .friday-nav{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));overflow:visible}.topbar .friday-nav button{min-width:0;white-space:normal}}
'''

NAVIGATION_HELPERS_JS = r'''
      function fridayDestination(value){
        const aliases={money:'dashboard',bank:'dashboard',bill:'statements',document:'statements',review:'library',settings:'privacy',assistant:'coach',activity:'library'};
        const raw=String(value||'home').replace(/^#/,'');
        const [original,part]=raw.split('/');const screen=aliases[original]||original;
        const parts=['overview','transactions','regular','findings','shield','spending-change'];
        return {screen,part:screen==='dashboard'&&parts.includes(part)?part:null};
      }
      function fridayParent(screen,part){
        if(screen==='dashboard'&&part)return 'dashboard';
        return ({'statement-review':'statements',statements:'library',plan:'dashboard',rehearsal:'dashboard',privacy:'profile',tools:'profile',document:'profile',review:'document'})[screen]||'home';
      }
'''

NAVIGATION_JS = r'''
    if(consumerOnly){
''' + NAVIGATION_HELPERS_JS + r'''
      const library=view('library','Choose the statements for this review. Saved imports stay private and can be reused.');
      titles.library='Your statements';library.querySelector('h1').textContent=titles.library;
      library.setAttribute('aria-label',titles.library);
      const libraryBody=element('div',null,'journey-library');library.append(libraryBody);
      let snapshot=null,unavailable=false,selectionBusy=false,routeKey=null,depth=0,completedPreview=false;const navSession=crypto.randomUUID();
      document.addEventListener('friday:statement-stage',e=>{if(e.detail.phase==='SAVED')completedPreview=true;});
      const action=(text,fn,cls='planner')=>{const b=element('button',text,cls);b.type='button';b.addEventListener('click',fn);return b;};
      const link=(text,route,cls='planner')=>action(text,()=>show(route),cls);
      function sourceLine(i){return i.account_alias+' · '+(i.account_type==='CREDIT_CARD'?'Card':'Bank')+' · '+(i.period?i.period.start+' to '+i.period.end:'Dates unavailable')+' · '+i.row_count+' rows · file '+i.source_sha256.slice(0,8);}
      const bars=new Map();for(const route of ['statements','dashboard','coach','plan','rehearsal']){const bar=element('section',null,'journey-source');bar.setAttribute('aria-label','Statements in this review');const heading=views[route].querySelector('.screen-heading');heading.after(bar);bars.set(route,bar);}
      function paintSources(){for(const [route,bar] of bars){bar.replaceChildren();const copy=element('div');if(!snapshot){copy.append(element('strong','Loading your statement selection…'));bar.append(copy);continue;}const selected=snapshot.imports.filter(i=>!i.excluded);bar.dataset.empty=String(!selected.length);copy.append(element('strong',selected.length?selected.length+' statement'+(selected.length===1?'':'s')+' in this review':'New review · no statements selected'));copy.append(element('p',selected.length?snapshot.summary.period.start+' to '+snapshot.summary.period.end+' · '+snapshot.summary.transaction_count+' entries · review v'+snapshot.revision:snapshot.imports.length?'Earlier imports are saved in Your statements, outside this analysis.':'Add a statement to begin. Nothing has been assumed.'));
          if(selected.length){const names=element('details');names.append(element('summary','Which statements?'));const list=element('ul',null,'journey-source-list');selected.forEach(i=>list.append(element('li',sourceLine(i))));names.append(list);copy.append(names);}bar.append(copy,link('Choose statements','library'));}
        const context=everydayAssistant.querySelector('.studio-context-button');if(context&&snapshot){context.title='Review v'+snapshot.revision+' · '+snapshot.summary.statement_count+' selected statement(s). Choose sharing explicitly.';}
      }
      function renderLibrary(){libraryBody.replaceChildren();if(!snapshot){libraryBody.append(element('p',unavailable?'Statements could not be loaded. Reload before changing your review.':'Loading your saved statements…','journey-status'));if(unavailable)libraryBody.append(action('Reload statements',()=>root.statementWorkspace.reload()));return;}
        const data=snapshot;const controls=element('div',null,'journey-actions');controls.append(link('Add a statement','statements','run'),action('Start a new review',()=>freshDialog.showModal()),action('Reload',()=>root.statementWorkspace.reload()));libraryBody.append(controls);
        const hint=element('p',data.imports.length?'Tick the statements to include, then apply. Unticked imports stay saved. This selection is shared across your Friday tabs.':'No saved statements yet. Add a bank export, review its rows, then save.','journey-status');libraryBody.append(hint);
        if(!data.imports.length){const empty=element('div',null,'journey-empty');empty.append(element('h2','One statement is enough.'),element('p','Friday will prepare your charts and review queue after you confirm the extracted rows.'));libraryBody.append(empty);return;}
        const form=element('form',null,'journey-library'),choices=[];
        data.imports.forEach(i=>{const row=element('section',null,'journey-library-item'),label=element('label',null,'journey-library-row'),check=element('input');check.type='checkbox';check.checked=!i.excluded;check.value=i.source_sha256;check.setAttribute('aria-label','Include '+sourceLine(i));const copy=element('div');copy.append(element('strong',i.account_alias+' · '+(i.account_type==='CREDIT_CARD'?'Credit card':'Bank account')),element('small',(i.period?i.period.start+' — '+i.period.end:'Dates unavailable')+' · '+i.row_count+' rows'),element('small','File '+i.source_sha256.slice(0,8)+' · '+(i.excluded?'Saved, not in this review':'Included in charts and optional AI context')));label.append(check,copy);choices.push(check);const proof=element('details');proof.append(element('summary','Source checks · '+(i.reconciliation?.overall_status||'UNKNOWN').toLowerCase()),element('p','Friday checks arithmetic and extraction evidence, not bank authenticity. File contents and original filenames are not retained.'));for(const [name,result] of Object.entries(i.reconciliation?.checks||{}))proof.append(element('p',name.replaceAll('_',' ')+': '+result.status.toLowerCase()));row.append(label,proof);form.append(row);});
        const status=element('p','Changes apply only when you press Apply.','journey-status');status.setAttribute('role','status');const apply=element('button','Apply & see my money','run');apply.type='submit';form.append(apply,status);form.addEventListener('submit',async e=>{e.preventDefault();if(selectionBusy)return;selectionBusy=true;apply.disabled=true;status.textContent='Updating this review…';try{await root.statementWorkspace.select(choices.filter(c=>c.checked).map(c=>c.value),data);show('dashboard');toast('Analysis updated. No saved rows were deleted.');}catch{status.textContent='Selection was not confirmed. Reload statements; earlier results may be stale.';}finally{selectionBusy=false;apply.disabled=false;}});libraryBody.append(form);
      }
      const freshDialog=element('dialog',null,'studio-dialog');freshDialog.setAttribute('aria-labelledby','fresh-review-title');freshDialog.append(element('h2','Start a new review?'));freshDialog.querySelector('h2').id='fresh-review-title';freshDialog.append(element('p','All earlier statements stay saved. They will be excluded from charts and AI answers until you select them again. Nothing is deleted.'));const freshStatus=element('p','','journey-status');freshStatus.setAttribute('role','status');const cancel=action('Keep this review',()=>freshDialog.close()),fresh=action('Start new review',async()=>{if(selectionBusy||!snapshot)return;selectionBusy=true;fresh.disabled=true;cancel.disabled=true;freshStatus.textContent='Starting a clean analysis…';try{if(snapshot.imports.length)await root.statementWorkspace.select([],snapshot,true);else root.statementWorkspace.resetPreview();freshDialog.close();show('statements');toast('New review. Your earlier imports are still saved.');}catch{freshStatus.textContent='New review was not confirmed. Reload statements before trying again.';}finally{selectionBusy=false;fresh.disabled=false;cancel.disabled=false;}},'run');const freshActions=element('div',null,'journey-actions');freshActions.append(cancel,fresh);freshDialog.append(freshActions,freshStatus);document.body.append(freshDialog);freshDialog.addEventListener('close',()=>{freshStatus.textContent='';libraryBody.querySelector('button')?.focus();});
      document.addEventListener('friday:portfolio-ready',e=>{const changed=!snapshot||snapshot.revision!==e.detail.revision||snapshot.workspace_generation!==e.detail.workspace_generation;snapshot=e.detail;unavailable=false;paintSources();if(active==='library'&&changed)renderLibrary();});
      document.addEventListener('friday:portfolio-unavailable',()=>{snapshot=null;unavailable=true;paintSources();renderLibrary();});
      for(const b of document.querySelectorAll('.friday-nav [data-screen-link=statements]'))b.dataset.screenLink='library';
      for(const b of document.querySelectorAll('.friday-nav [data-screen-link=coach] span'))b.textContent='Ask Friday';
      titles.dashboard='Your money, checked.';
      const accountOptions=views.statements.querySelector('.statement-account-options');if(accountOptions)accountOptions.open=true;
      const aliasField=$('portfolio-alias');if(aliasField)aliasField.placeholder='For example, ICICI salary account';
      const formats=views.statements.querySelector('.statement-consent-details');if(formats){const copy=formats.querySelector('p');if(copy)copy.textContent='INR bank and card statements. PDF: up to 6 pages / 200 rows, including configured scan reading. CSV: up to 500 rows, with automatic recognition of supported bank-export headings and preambles. Unknown or ambiguous formats stop with no partial import. Not every bank format has been validated.';}
      const listen=action('Listen',()=>openVoice(),'journey-listen');listen.setAttribute('aria-label','Listen to my review');listen.title='Optional spoken statement briefing. No microphone or automatic audio.';nav.append(listen);
      const chatVoice=action('Listen to my review',()=>openVoice(),'studio-link-button');everydayAssistant.querySelector('.studio-chat-footer').append(chatVoice);
      function openVoice(){if(!snapshot?.summary.transaction_count){show('library');toast('Select a saved statement or add one before creating a briefing.');return;}show('dashboard');const voice=views.dashboard.querySelector('.work-voice');if(!voice){toast('Review is loading. Try Listen again once the charts appear.');return;}voice.open=true;voice.querySelector('summary')?.focus();voice.scrollIntoView({behavior:document.documentElement.dataset.motion==='off'||matchMedia('(prefers-reduced-motion:reduce)').matches?'auto':'smooth',block:'center'});}
      moreItems.replaceChildren();[['plan','Build a money plan'],['rehearsal','Explore a purchase'],['tools','Diary & runway']].forEach(([route,label])=>moreItems.append(link(label,route)));
      more.querySelector('summary').firstElementChild.textContent='Optional tools · separate from statements';
      const sampleGuide=element('a','Try a sample · quick walkthrough','journey-sample-guide');sampleGuide.href='/assets/friday-judge-guide.html';sampleGuide.target='_blank';sampleGuide.rel='noopener';home.querySelector('.studio-welcome').append(sampleGuide);
      const menuGuide=sampleGuide.cloneNode(true);menuGuide.textContent='Sample statements & walkthrough';moreItems.append(menuGuide);
      const beforeNavigation=show;
      show=function(value,push=true){const target=fridayDestination(value);if(!views[target.screen]||views[target.screen].dataset.consumerExcluded==='true'){if(routeKey===null)show('home',false);toast('This older page is not part of your statement review. Open Statements or My money.');return;}
        const key=target.screen+(target.part?'/'+target.part:'');if(key===routeKey){if(!push&&location.hash!=='#'+key)history.replaceState(history.state,'','#'+key);return;}
        if(target.screen==='dashboard'&&(target.part||!['coach','plan'].includes(active)))root.selectMoneyTab?.(target.part||'overview');
        const replacePreview=push&&active==='statement-review'&&((completedPreview&&target.screen==='dashboard')||target.screen==='statements');
        beforeNavigation(target.screen,false);routeKey=key;if(push&&!replacePreview){depth++;history.pushState({fridayNavigation:{session:navSession,depth}},'','#'+key);}else{const saved=history.state?.fridayNavigation;depth=saved?.session===navSession?saved.depth:0;history.replaceState({fridayNavigation:{session:navSession,depth}},'','#'+key);}completedPreview=false;
        const group=['library','statements','statement-review'].includes(target.screen)?'library':['dashboard','plan','rehearsal'].includes(target.screen)?'dashboard':target.screen;nav.querySelectorAll('[data-screen-link]').forEach(b=>b.setAttribute('aria-current',b.dataset.screenLink===group?(target.screen===group?'page':'location'):'false'));
        const dock=root.querySelector('.studio-chat-dock');if(dock&&views[target.screen].parentNode===root)root.insertBefore(views[target.screen],dock);
        const parent=fridayParent(target.screen,target.part),back=views[target.screen].querySelector('.screen-back');if(back){back.removeAttribute('data-screen-link');back.textContent=depth?'Back':'Back to '+({home:'Home',library:'Statements',statements:'Add a statement',dashboard:'My money',profile:'My account',document:'Document review'})[parent];back.onclick=()=>{if(depth>0)history.back();else show(parent);};}
        const title=views[target.screen].querySelector('h1');if(title&&target.screen==='dashboard')title.textContent=target.part?({transactions:'Your transactions',regular:'Regular payment patterns',findings:'Your review history',shield:'Refund evidence','spending-change':'What changed'})[target.part]||'Your money, checked.':titles.dashboard;
        if(target.screen==='library'){renderLibrary();root.statementWorkspace.reload();}
        if(target.screen==='statements'){const path=views.statements.querySelector('.statement-path');if(path)path.setAttribute('aria-label','Step 1 of 3: upload, review, understand');}
        paintSources();
      };
      root.navigateMoneyTab=tab=>show('dashboard/'+tab);
      document.addEventListener('click',e=>{const b=e.target.closest('.work-more button,.checkup-tabs button');if(!b)return;const byLabel={'All entries':'transactions','Transactions':'transactions','Payment patterns':'regular','Regular payments':'regular','Review history':'findings','My workbench':'overview'};const key=byLabel[b.textContent.trim()];if(key){e.preventDefault();e.stopImmediatePropagation();show(key==='overview'?'dashboard':'dashboard/'+key);}},true);
      root.statementWorkspace.reload();
    }
'''
